import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
function setup(s = {}, t = {}) {
 const orders = new InMemoryOrderStore([
 {id:'alpha',customerId:'alice',status:'pending',items:['s','s'],...s},
 {id:'beta',customerId:'alice',status:'pending',items:['t'],...t},
 {id:'gamma',customerId:'bob',status:'pending',items:['u']}]);
 let saves=0; const save=orders.save.bind(orders); orders.save=o=>{saves++;save(o)};
 const router=orderRoutes(new Router(),{orders,sessions:{lookup:token=>token==='secret'?{id:'alice'}:undefined}});
 return {orders,router,saves:()=>saves};
}
function run(label, app, body:any={sourceId:'alpha',targetId:'beta'}, authorization:any='Bearer secret') {
 const before=structuredClone(app.orders.all()); let result;
 try {result=app.router.handle({method:'POST',path:'/orders/merge',headers:{authorization},body}).status;}catch(e){result='THROW '+e.constructor.name;}
 const unchanged=JSON.stringify(before)===JSON.stringify(app.orders.all());
 console.log(label,JSON.stringify({result,unchanged,saves:app.saves(),orders:app.orders.all()}));return result;
}
const ok=setup(); assert.equal(run('R1/R6 normal',ok),200);
assert.deepEqual(ok.orders.get('beta'),{id:'beta',customerId:'alice',status:'pending',items:['t','s','s']});
assert.equal(ok.orders.get('alpha')?.status,'cancelled');
assert.deepEqual(ok.orders.get('gamma')?.items,['u']);
run('R4 replay',ok);
for(const token of [undefined,'Bearer invalid','Basic secret','']) run('R2 credential '+String(token),setup(),undefined,token===undefined?null:token);
for(const [s,t] of [[{customerId:'bob'},{}],[{},{customerId:'bob'}],[{customerId:'bob'},{customerId:'bob'}]]) run('R3 ownership',setup(s,t));
for(const side of ['sourceId','targetId']) run('R4 missing '+side,setup(),{sourceId:'alpha',targetId:'beta',[side]:'missing'});
for(const status of ['shipped','cancelled']) {run('R4/R6 source '+status,setup({status}));run('R4/R6 target '+status,setup({}, {status}));}
for(const body of [null,undefined,[],3,'bad',{}, {sourceId:3,targetId:'beta'},{sourceId:'',targetId:'beta'},{sourceId:'alpha',targetId:''},{sourceId:'alpha',targetId:'alpha'}]) {
 if(body===undefined){const app=setup();try{console.log('R5 absent',app.router.handle({method:'POST',path:'/orders/merge',headers:{authorization:'Bearer secret'}}))}catch(e){console.log('R5 absent THROW',e.constructor.name)};}
 else run('R5 '+JSON.stringify(body),setup(),body);
}
// Empty identifier resource demonstrates lack of explicit nonempty validation.
run('R5 existing empty identifier',setup({id:''}),{sourceId:'',targetId:'beta'});
EOF
node evaluator/independent-probes.ts
